#!/usr/bin/env python3
"""Day 026: append-only KV log (stdlib only)."""
from __future__ import annotations

import argparse
import time
from pathlib import Path

LOG = Path("data/kv.log")


def append_record(key: str, value: str | None) -> None:
LOG.parent.mkdir(parents=True, exist_ok=True)
line = f"{key}=\n" if value is None else f"{key}={value}\n"
with LOG.open("a", encoding="utf-8") as f:
f.write(line)


def load_latest(truncate_last: bool = False) -> dict[str, str | None]:
if not LOG.exists():
return {}
lines = LOG.read_text(encoding="utf-8").splitlines()
if truncate_last and lines:
lines = lines[:-1]
state: dict[str, str | None] = {}
for line in lines:
if "=" not in line:
continue
k, v = line.split("=", 1)
state[k] = v if v != "" else None
return state


def get(key: str, state: dict[str, str | None]) -> str | None:
if key not in state or state[key] is None:
return None
return state[key]


def main() -> None:
p = argparse.ArgumentParser(description="Append-only KV log lab")
p.add_argument("--keys", type=int, default=500, help="unique keys to write")
p.add_argument("--overwrites", type=int, default=3, help="overwrite passes")
p.add_argument("--break", dest="break_mode", action="store_true", help="simulate crash mid-append")
args = p.parse_args()

if LOG.exists():
LOG.unlink()

t0 = time.perf_counter()
for n in range(args.overwrites):
for i in range(args.keys):
append_record(f"k{i}", f"v{n}-{i}")
write_ms = (time.perf_counter() - t0) * 1000

if args.break_mode:
raw = LOG.read_text(encoding="utf-8")
last_nl = raw.rfind("\n")
if last_nl > 0:
LOG.write_text(raw[: last_nl + 1], encoding="utf-8")

state = load_latest(truncate_last=args.break_mode)
t1 = time.perf_counter()
hits = sum(1 for i in range(args.keys) if get(f"k{i}", state) is not None)
read_ms = (time.perf_counter() - t1) * 1000

file_bytes = LOG.stat().st_size if LOG.exists() else 0
logical = args.keys
amp = file_bytes / max(1, logical * 8)

print(f"records={LOG.read_text().count(chr(10)) if LOG.exists() else 0}")
print(f"unique_keys={len(state)} hits={hits}")
print(f"write_ms={write_ms:.2f} scan_read_ms={read_ms:.2f}")
print(f"file_bytes={file_bytes} space_amp_ratio~={amp:.1f}x")
if args.break_mode:
print("break_mode=truncated_last_line (check for partial record handling)")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 028: LSM-style compaction simulator."""
from __future__ import annotations

import argparse
import json
import time
from pathlib import Path

DIR = Path("data/segments")


def write_seg(name: str, data: dict[str, str]) -> None:
DIR.mkdir(parents=True, exist_ok=True)
(DIR / name).write_text(json.dumps(dict(sorted(data.items()))), encoding="utf-8")


def list_segs() -> list[Path]:
return sorted(DIR.glob("*.json"))


def get(key: str) -> tuple[str | None, int]:
val, touched = None, 0
for p in list_segs():
touched += 1
data = json.loads(p.read_text(encoding="utf-8"))
if key in data:
val = data[key]
return val, touched


def compact() -> float:
merged: dict[str, str] = {}
for p in list_segs():
merged.update(json.loads(p.read_text(encoding="utf-8")))
p.unlink()
write_seg("compact.json", merged)
return sum(len(json.dumps(json.loads(p.read_text()))) for p in list_segs()) if list_segs() else len(json.dumps(merged))


def main() -> None:
p = argparse.ArgumentParser(description="Compaction lab")
p.add_argument("--flushes", type=int, default=6)
p.add_argument("--compact", action="store_true")
p.add_argument("--break", dest="skip", action="store_true", help="skip compaction")
args = p.parse_args()

if DIR.exists():
for f in DIR.glob("*.json"):
f.unlink()

keys = [f"k{i}" for i in range(100)]
for i in range(args.flushes):
batch = {k: f"v{i}" for k in keys[i * 10 : (i + 1) * 10]}
write_seg(f"seg{i}.json", batch)

t0 = time.perf_counter()
if args.compact and not args.skip:
compact()
compact_ms = (time.perf_counter() - t0) * 1000

_, fanout = get("k55")
segs = len(list_segs())
total_bytes = sum(p.stat().st_size for p in list_segs())

print(f"segments={segs} read_fanout={fanout} total_bytes={total_bytes}")
print(f"compact_ran={args.compact and not args.skip} compact_ms={compact_ms:.2f}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 030: toy B-tree vs LSM benchmark."""
from __future__ import annotations

import argparse
import json
import random
import time
from pathlib import Path


class LSM:
def __init__(self):
self.segs: list[dict[str, int]] = []

def put(self, k: str, v: int) -> None:
self.segs.append({k: v})

def get(self, k: str) -> int | None:
val, fanout = None, 0
for seg in reversed(self.segs):
fanout += 1
if k in seg:
val = seg[k]
return val, fanout


class BTreeKV:
def __init__(self):
self.pages: dict[str, int] = {}

def put(self, k: str, v: int) -> None:
self.pages[k] = v

def get(self, k: str) -> tuple[int | None, int]:
return self.pages.get(k), 1


def bench(name: str, store, keys: list[str], updates: int) -> None:
t0 = time.perf_counter()
for i, k in enumerate(keys):
store.put(k, i)
write_ops = len(keys)
write_ms = (time.perf_counter() - t0) * 1000

t1 = time.perf_counter()
fanouts = []
for _ in range(updates):
k = random.choice(keys)
if name == "lsm":
cur, f = store.get(k)
fanouts.append(f)
store.put(k, (cur or 0) + 1)
else:
cur, f = store.get(k)
fanouts.append(f)
store.put(k, (cur or 0) + 1)
upd_ms = (time.perf_counter() - t1) * 1000

print(f"[{name}] write_ops={write_ops} write_ms={write_ms:.2f} update_ops={updates} update_ms={upd_ms:.2f}")
if fanouts:
print(f"[{name}] avg_read_fanout={sum(fanouts)/len(fanouts):.2f} max_fanout={max(fanouts)}")


def main() -> None:
p = argparse.ArgumentParser(description="B-tree vs LSM toy benchmark")
p.add_argument("--keys", type=int, default=800)
p.add_argument("--updates", type=int, default=400)
args = p.parse_args()

keys = [f"k{i}" for i in range(args.keys)]
bench("btree", BTreeKV(), keys, args.updates)
bench("lsm", LSM(), keys, args.updates)


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 031: primary + secondary index simulator."""
from __future__ import annotations

import argparse
import random
import time


class Table:
def __init__(self, secondary: bool):
self.rows: dict[int, dict] = {}
self.pk = {}
self.email_idx: dict[str, list[int]] = {}
self.secondary = secondary
self.write_touches = 0

def insert(self, rid: int, email: str, status: str) -> None:
self.write_touches += 1
self.rows[rid] = {"email": email, "status": status}
self.pk[rid] = rid
if self.secondary:
self.write_touches += 1
self.email_idx.setdefault(email, []).append(rid)

def update_email(self, rid: int, new_email: str) -> None:
old = self.rows[rid]["email"]
self.write_touches += 1
self.rows[rid]["email"] = new_email
if self.secondary:
self.write_touches += 2
self.email_idx[old].remove(rid)
self.email_idx.setdefault(new_email, []).append(rid)

def get_by_id(self, rid: int) -> dict | None:
return self.rows.get(rid)

def get_by_email(self, email: str) -> list[dict]:
if not self.secondary:
return [r for r in self.rows.values() if r["email"] == email]
return [self.rows[i] for i in self.email_idx.get(email, [])]


def main() -> None:
p = argparse.ArgumentParser(description="Secondary index lab")
p.add_argument("--rows", type=int, default=1000)
p.add_argument("--updates", type=int, default=200)
p.add_argument("--no-index", action="store_true")
args = p.parse_args()

t = Table(secondary=not args.no_index)
rng = random.Random(1)
emails = [f"u{i}@example.com" for i in range(args.rows)]

t0 = time.perf_counter()
for i, e in enumerate(emails):
t.insert(i, e, "active")
for _ in range(args.updates):
rid = rng.randrange(args.rows)
t.update_email(rid, f"changed{rid}@example.com")
ms = (time.perf_counter() - t0) * 1000

sample = t.get_by_email("changed0@example.com")
print(f"secondary_index={not args.no_index} write_touches={t.write_touches} elapsed_ms={ms:.2f}")
print(f"lookup_by_email_hits={len(sample)}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 034: toy query planner + executor."""
from __future__ import annotations

import argparse
import json
import time


def execute(plan: dict, rows: list[dict]) -> tuple[list[dict], dict]:
stats = {"ops": 0, "rows_in": len(rows), "rows_out": 0}
cur = rows
for step in plan["steps"]:
stats["ops"] += 1
if step["op"] == "seq_scan":
cur = [r for r in cur if step.get("filter")(r)]
elif step["op"] == "index_scan":
key, val = step["eq"]
cur = [r for r in cur if r.get(key) == val]
elif step["op"] == "project":
cols = step["cols"]
cur = [{c: r[c] for c in cols} for r in cur]
stats["rows_out"] = len(cur)
return cur, stats


def main() -> None:
p = argparse.ArgumentParser(description="Query execution lab")
p.add_argument("--no-index", action="store_true")
args = p.parse_args()

rows = [{"id": i, "status": "active" if i % 3 else "paused"} for i in range(5000)]

if args.no_index:
plan = {"steps": [{"op": "seq_scan", "filter": lambda r: r["status"] == "active"}]}
else:
plan = {"steps": [{"op": "index_scan", "eq": ("status", "active")}]}

t0 = time.perf_counter()
out, stats = execute(plan, rows)
ms = (time.perf_counter() - t0) * 1000

print(f"plan={json.dumps(plan['steps'], default=str)}")
print(f"result_rows={len(out)} ops={stats['ops']} elapsed_ms={ms:.3f}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 036: schema evolution compatibility matrix."""
from __future__ import annotations

import argparse
import json


V1 = {"fields": ["id", "name"]}
V2 = {"fields": ["id", "name", "nickname"], "defaults": {"nickname": "anon"}}


def write_v1(rec: dict) -> bytes:
return json.dumps({k: rec[k] for k in V1["fields"]}).encode()


def write_v2(rec: dict) -> bytes:
payload = {k: rec.get(k, V2["defaults"].get(k)) for k in V2["fields"]}
return json.dumps(payload).encode()


def read_v1(blob: bytes) -> dict:
data = json.loads(blob)
return {k: data[k] for k in V1["fields"] if k in data}


def read_v2(blob: bytes) -> dict:
data = json.loads(blob)
out = {}
for k in V2["fields"]:
out[k] = data.get(k, V2["defaults"].get(k))
return out


def cell(r: str, w: str, rec: dict) -> bool:
writer = write_v1 if w == "v1" else write_v2
reader = read_v1 if r == "v1" else read_v2
try:
back = reader(writer(rec))
return back["id"] == rec["id"] and back["name"] == rec["name"]
except Exception:
return False


def main() -> None:
p = argparse.ArgumentParser(description="Schema evolution lab")
p.add_argument("--break", dest="break_mode", action="store_true", help="rename id without bridge")
args = p.parse_args()

rec = {"id": 7, "name": "ada", "nickname": "ad"}
if args.break_mode:
bad = json.dumps({"user_id": 7, "name": "ada"}).encode()
ok = "user_id" in json.loads(bad.decode())
print(f"breaking_rename_detected={ok}")
return

for r in ("v1", "v2"):
for w in ("v1", "v2"):
print(f"reader={r} writer={w} ok={cell(r, w, rec)}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 037: DIY protobuf-style tagged encoding (stdlib only)."""
from __future__ import annotations

import argparse
import struct

# field_number -> (wire_type, name) wire_type 0=varint 2=length-delimited
SCHEMA_V1 = {1: (0, "id"), 2: (2, "name")}
SCHEMA_V2 = {1: (0, "id"), 2: (2, "name"), 3: (2, "email")}


def encode_varint(n: int) -> bytes:
out = bytearray()
while True:
b = n & 0x7F
n >>= 7
out.append(b | (0x80 if n else 0))
if not n:
break
return bytes(out)


def tag(field: int, wire: int) -> bytes:
return encode_varint((field << 3) | wire)


def encode_v1(rec: dict) -> bytes:
out = bytearray()
out += tag(1, 0) + encode_varint(rec["id"])
name = rec["name"].encode()
out += tag(2, 2) + encode_varint(len(name)) + name
return bytes(out)


def decode(blob: bytes, schema: dict) -> dict:
i, out = 0, {}
while i < len(blob):
key, i = _varint(blob, i)
field, wire = key >> 3, key & 7
if field not in schema:
i = _skip(wire, blob, i)
continue
exp_wire, name = schema[field]
if wire == 0:
val, i = _varint(blob, i)
elif wire == 2:
ln, i = _varint(blob, i)
val = blob[i:i+ln].decode(); i += ln
else:
i = _skip(wire, blob, i); continue
out[name] = val
return out


def _varint(blob: bytes, i: int) -> tuple[int, int]:
shift = n = 0
while True:
b = blob[i]; i += 1
n |= (b & 0x7F) << shift
if not (b & 0x80):
return n, i
shift += 7


def _skip(wire: int, blob: bytes, i: int) -> int:
if wire == 0:
_, i = _varint(blob, i)
elif wire == 2:
ln, i = _varint(blob, i); i += ln
return i


def main() -> None:
p = argparse.ArgumentParser(description="DIY protobuf lab")
p.add_argument("--break", dest="break_mode", action="store_true", help="recycle field 2 for int age")
args = p.parse_args()

rec = {"id": 42, "name": "ada", "email": "a@x.com"}
v1_bytes = encode_v1(rec)
print(f"v1_bytes_len={len(v1_bytes)} v2_reader_on_v1={decode(v1_bytes, SCHEMA_V2)}")

v2_bytes = encode_v1(rec) + tag(3, 2) + encode_varint(len(rec["email"])) + rec["email"].encode()
print(f"v1_reader_on_v2={decode(v2_bytes, SCHEMA_V1)}")

if args.break_mode:
poison = tag(2, 0) + encode_varint(99)
mis = decode(v1_bytes + poison, SCHEMA_V2)
print(f"break_recycled_field2={mis}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 038: Avro-style writer/reader schema resolution (stdlib)."""
from __future__ import annotations

import argparse
import json


WRITER = {"fields": ["id", "name"]}
READER = {"fields": ["id", "name", "tier"], "defaults": {"tier": "free"}}


def write(rec: dict, schema: dict) -> list:
return [rec.get(f) for f in schema["fields"]]


def resolve(payload: list, writer: dict, reader: dict) -> dict:
wmap = {f: payload[i] for i, f in enumerate(writer["fields"]) if i < len(payload)}
out = {}
defaults = reader.get("defaults", {})
for f in reader["fields"]:
if f in wmap:
out[f] = wmap[f]
elif f in defaults:
out[f] = defaults[f]
else:
raise KeyError(f"missing required field {f} with no default")
return out


def main() -> None:
p = argparse.ArgumentParser(description="Avro-style schema lab")
p.add_argument("--break", dest="break_mode", action="store_true", help="reader drops field without default")
args = p.parse_args()

rec = {"id": 3, "name": "bob"}
blob = write(rec, WRITER)
ok = resolve(blob, WRITER, READER)
print(f"forward_ok={ok}")

if args.break_mode:
bad_reader = {"fields": ["id", "tier"]}
try:
resolve(blob, WRITER, bad_reader)
except KeyError as e:
print(f"break_error={e}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 039: dataflow deploy-order simulator."""
from __future__ import annotations

import argparse


def step(producer: str, consumer: str, change: str) -> tuple[bool, str]:
if change == "add_field":
if consumer == "old" and producer == "new":
return False, "consumer cannot read new field"
return True, "ok"
if change == "remove_field":
if consumer == "new" and producer == "old":
return False, "consumer expects field producer no longer sends"
return True, "ok"
return False, "unknown change"


def timeline(order: list[str], change: str) -> None:
prod, cons = "old", "old"
for action in order:
if action == "upgrade_consumer":
cons = "new"
elif action == "upgrade_producer":
prod = "new"
safe, msg = step(prod, cons, change)
print(f"{action:20} producer={prod} consumer={cons} safe={safe} note={msg}")


def main() -> None:
p = argparse.ArgumentParser(description="Dataflow compatibility lab")
p.add_argument("--change", choices=["add_field", "remove_field"], default="add_field")
p.add_argument("--break", dest="break_mode", action="store_true", help="producer first (unsafe for add)")
args = p.parse_args()

if args.break_mode:
timeline(["upgrade_producer", "upgrade_consumer"], args.change)
else:
timeline(["upgrade_consumer", "upgrade_producer"], args.change)


if __name__ == "__main__":
main()

