"""Day 040: API/event version compatibility checker."""
from __future__ import annotations

import argparse
import json


EVENTS = {
"order.created.v1": {"required": ["order_id", "amount"]},
"order.created.v2": {"required": ["order_id", "amount", "currency"]},
