#!/usr/bin/env python3
"""Day 041: leader/follower log replication."""
from __future__ import annotations

import argparse
import json
import time
from pathlib import Path

LOG = Path("data/repl.log")
STATE = Path("data/state.json")


def leader_append(op: dict) -> int:
LOG.parent.mkdir(parents=True, exist_ok=True)
entries = []
if LOG.exists():
entries = [json.loads(x) for x in LOG.read_text().splitlines() if x]
entries.append(op)
LOG.write_text("\n".join(json.dumps(e) for e in entries) + "\n", encoding="utf-8")
return len(entries)


def follower_apply(up_to: int | None = None) -> dict:
state = {"k": {}}
if not LOG.exists():
return state
lines = [json.loads(x) for x in LOG.read_text().splitlines() if x]
if up_to is not None:
lines = lines[:up_to]
for e in lines:
if e["op"] == "put":
state["k"][e["key"]] = e["val"]
elif e["op"] == "del":
state["k"].pop(e["key"], None)
STATE.write_text(json.dumps(state), encoding="utf-8")
return state


def main() -> None:
p = argparse.ArgumentParser(description="Leader-follower replication lab")
p.add_argument("--ops", type=int, default=5)
p.add_argument("--break", dest="break_mode", action="store_true", help="follower stops mid-stream")
args = p.parse_args()

if LOG.exists():
LOG.unlink()

for i in range(args.ops):
leader_append({"op": "put", "key": f"k{i}", "val": i})

applied = args.ops - 1 if args.break_mode else args.ops
st = follower_apply(applied)
lag = args.ops - applied

print(f"leader_entries={args.ops} follower_applied={applied} lag_entries={lag}")
print(f"follower_keys={len(st['k'])} state={st['k']}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 042: sync vs async replication latency/durability."""
from __future__ import annotations

import argparse
import time


class Cluster:
def __init__(self, sync: bool, follower_delay_ms: float):
self.sync = sync
self.delay = follower_delay_ms / 1000
self.leader_log: list[str] = []
self.follower_log: list[str] = []

def write(self, val: str) -> tuple[float, bool]:
t0 = time.perf_counter()
self.leader_log.append(val)
if self.sync:
time.sleep(self.delay)
self.follower_log.append(val)
else:
pass
return (time.perf_counter() - t0) * 1000, len(self.follower_log) == len(self.leader_log)

def replicate_async(self) -> None:
while len(self.follower_log) < len(self.leader_log):
time.sleep(self.delay)
self.follower_log.append(self.leader_log[len(self.follower_log)])

def lose_leader(self) -> int:
return len(self.leader_log) - len(self.follower_log)


def main() -> None:
p = argparse.ArgumentParser(description="Sync vs async replication lab")
p.add_argument("--sync", action="store_true")
p.add_argument("--delay-ms", type=float, default=5.0)
p.add_argument("--break", dest="break_mode", action="store_true", help="crash leader before async replicate")
args = p.parse_args()

c = Cluster(args.sync, args.delay_ms)
lats = []
for i in range(20):
ms, _ = c.write(f"e{i}")
lats.append(ms)

if not args.sync and not args.break_mode:
c.replicate_async()
lost = c.lose_leader() if args.break_mode and not args.sync else 0

mode = "sync" if args.sync else "async"
print(f"mode={mode} avg_write_ms={sum(lats)/len(lats):.3f} max_ms={max(lats):.3f}")
print(f"leader={len(c.leader_log)} follower={len(c.follower_log)} possible_lost={lost}")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 043: follower bootstrap via snapshot + log replay."""
from __future__ import annotations

import argparse
import json


def snapshot(state: dict, offset: int) -> dict:
return {"offset": offset, "data": dict(state)}


def replay(base: dict, entries: list[dict], min_offset: int) -> tuple[dict, int]:
st = dict(base)
rejected = 0
for e in entries:
if e["offset"] <= min_offset:
rejected += 1
continue
st.update(e["delta"])
return st, rejected


def main() -> None:
p = argparse.ArgumentParser(description="Follower bootstrap lab")
p.add_argument("--break", dest="break_mode", action="store_true", help="include pre-snapshot entries")
args = p.parse_args()

leader = {"balance": 100, "version": 3}
snap = snapshot(leader, offset=3)
log = [
{"offset": 2, "delta": {"balance": 999}},
